/* ============================================================
   LABI — trợ lý ngôn ngữ (cửa sổ nổi): hỏi đáp + phân tích tệp âm thanh
   ============================================================ */
function mdLite(s){
  let t = esc(String(s));
  t = t.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  t = t.replace(/`([^`]+)`/g, '<code>$1</code>');
  t = t.replace(/\n/g, '<br>');
  return t;
}
function asstErrMsg(e){
  const map = {
    'offline':  'Tính năng này cần máy chủ AI. Hãy mở app qua link đã cấu hình Worker (js/config.js), đừng mở bằng file trực tiếp.',
    'no-server':'Không gọi được máy chủ AI. Kiểm tra URL Worker trong js/config.js và secret của Worker.',
    'no-key':   'Máy chủ AI chưa có khoá API. Đặt secret GEMINI_API_KEY cho Worker.',
    'no-gemini':'Phân tích âm thanh cần Gemini. Hãy đặt secret GEMINI_API_KEY cho Worker.'
  };
  return map[e] || ('Lỗi: ' + e);
}


function asstChatTab(){
  const A = state.assistant;
  const body = A.messages.length
    ? A.messages.map(m => `
        <div class="asst-msg ${m.role}">
          <div class="asst-bubble">${m.role === 'user' ? esc(m.content) : mdLite(m.content)}</div>
        </div>`).join('')
    : `<div class="asst-hint">
        <p><b>Xin chào!</b> Mình có thể giúp bạn về tiếng Hàn: ngữ pháp, từ vựng, cách dùng, luyện TOPIK, mẹo học… Thử một câu hỏi:</p>
        <div class="asst-suggest">
          ${['Phân biệt 은/는 và 이/가','“-(으)ㄹ 수 있다” dùng thế nào?','Cách xưng hô lịch sự trong tiếng Hàn','Mẹo nhớ từ vựng nhanh']
            .map(s => `<button class="asst-chip" data-asst-ask="${esc(s)}">${esc(s)}</button>`).join('')}
        </div>
      </div>`;
  return `
  <div class="asst-chat">
    <div class="asst-msgs" id="asstMsgs">
      ${body}
      ${A.busy ? '<div class="asst-msg assistant"><div class="asst-bubble typing"><span></span><span></span><span></span></div></div>' : ''}
    </div>
    <div class="asst-input">
      <textarea id="asstInput" rows="1" placeholder="Hỏi về tiếng Hàn… (Enter để gửi)"${A.busy ? ' disabled' : ''}></textarea>
      <button class="pbtn primary" data-asst-send="1"${A.busy ? ' disabled' : ''}>Gửi</button>
      ${A.messages.length ? '<button class="pbtn" data-asst-clear="1" title="Xoá hội thoại">Xoá</button>' : ''}
    </div>
    <p class="asst-note">Chỉ hỗ trợ chủ đề học ngôn ngữ. Câu trả lời do AI tạo, có thể chưa chính xác tuyệt đối.</p>`
    + '</div>';
}

function asstAudioTab(){
  const A = state.assistant.audio;
  let body = '';
  if (A.busy)       body = `<div class="asst-audio-busy"><div class="asst-spin"></div><p>Đang phân tích “${esc(A.name)}”… có thể mất 10–30 giây.</p></div>`;
  else if (A.error) body = `<div class="asst-error">${esc(A.error)}</div>`;
  else if (A.result) body = asstAudioResult();
  return `
  <div class="asst-audio">
    <label class="asst-drop" for="asstFile">
      <div class="asst-drop-ico">🎧</div>
      <div><b>Chọn tệp âm thanh</b> để phân tích<br><small>mp3, m4a, wav, ogg… · nên ngắn (≤ ~2 phút) · tối đa ~15 MB</small></div>
      <input type="file" id="asstFile" accept="audio/*" hidden>
    </label>
    ${body}
    <p class="asst-note">Tệp được gửi tới máy chủ AI của bạn để phân tích, không lưu lại. Với tiếng Hàn, bấm vào từng từ để tra từ điển đầy đủ.</p>
  </div>`;
}

/* Một từ trong câu → nút bấm tra được (nghĩa nhanh lấy từ bản đồ gloss của AI) */
function asstWordBtn(tokenRaw, lang){
  const A = state.assistant.audio;
  const token = String(tokenRaw);
  const key = token.replace(/[.,!?…"'”’)\]}]+$/, '').replace(/^[("'“‘(\[{]+/, '');
  const g = (A.glossMap && (A.glossMap[token] || A.glossMap[key])) || { rom:'', vi:'' };
  const tip = [g.rom, g.vi].filter(Boolean).join(' · ');
  return `<button class="asst-word" data-asst-word="${esc(key || token)}" data-asst-lang="${esc(lang || '')}" data-asst-rom="${esc(g.rom || '')}" data-asst-vi="${esc(g.vi || '')}" title="${esc(tip)}">${esc(token)}</button>`;
}

function asstAudioResult(){
  const A = state.assistant.audio;
  const r = A.result || {};
  const isKo = /^ko/i.test(A.lang || r.lang || '');
  const segs = A.segments || [];
  const fullText = segs.map(s => s.ko).join(' ');
  const head = `<div class="asst-lang">Ngôn ngữ nhận diện: <b>${esc(r.langVi || r.lang || 'không rõ')}</b> · ${segs.length} câu${isKo ? ' · bấm vào từng từ để tra; từ chưa có sẽ hiện nút thêm vào từ điển' : ''}</div>`;

  // ---- Chế độ SỬA ngắt câu ----
  if (A.editing){
    const draft = segs.map(s => s.ko).join('\n');
    return `${head}
    <div class="asst-edit">
      <p class="asst-edit-hint"><b>Sửa cách ngắt câu:</b> mỗi <b>dòng</b> là một câu. Nhấn <b>Enter</b> để ngắt thành câu mới, xoá xuống dòng để <b>gộp</b> hai câu, sửa chữ nếu AI nghe sai.</p>
      <textarea id="asstEditBox" class="asst-edit-box ko" rows="${Math.min(Math.max(segs.length + 2, 6), 20)}">${esc(draft)}</textarea>
      <div class="asst-para-tools">
        <button class="pbtn primary" data-asst-edit-apply="1">Áp dụng &amp; dịch lại</button>
        <button class="pbtn" data-asst-edit-cancel="1">Huỷ</button>
      </div>
    </div>`;
  }

  // ---- Chế độ ĐỌC ----
  const tools = `<div class="asst-para-tools">
    <button class="pbtn" data-speak="${esc(fullText)}"><svg viewBox="0 0 24 24"><polygon points="6 4 20 12 6 20 6 4"></polygon></svg> Nghe cả đoạn</button>
    <button class="pbtn" data-asst-trans="1">${A.showVi ? 'Ẩn bản dịch' : 'Dịch từng câu'}</button>
    <button class="pbtn" data-asst-edit="1">✎ Sửa ngắt câu</button>
    <button class="pbtn" data-asst-audio-reset="1">↻ Tệp khác</button>
  </div>`;
  const lines = segs.map((s, i) => {
    const words = String(s.ko).split(/\s+/).filter(Boolean).map(tok => asstWordBtn(tok, A.lang || r.lang)).join(' ');
    return `<div class="asst-line">
      <button class="asst-line-play" data-speak="${esc(s.ko)}" title="Nghe câu ${i + 1}"><svg viewBox="0 0 24 24"><polygon points="6 4 20 12 6 20 6 4"></polygon></svg></button>
      <div class="asst-line-body">
        <div class="asst-line-ko ${isKo ? 'ko' : ''}">${words}</div>
        ${A.showVi ? `<div class="asst-line-vi">${s.vi ? esc(s.vi) : '<i>—</i>'}</div>` : ''}
      </div>
    </div>`;
  }).join('');
  return `${head}${tools}
    ${A.retranslating ? '<div class="asst-audio-busy"><div class="asst-spin"></div><p>Đang dịch lại theo cách ngắt mới…</p></div>' : ''}
    <div class="asst-lines">${lines}</div>`;
}

/* Thẻ nghĩa nhanh cho từ không phải tiếng Hàn (tiếng Hàn dùng bảng tra đầy đủ) */
function asstGloss(w, rom, vi){
  const el = wordPanel();
  el.innerHTML = `
    <div class="wp-head">
      <div>
        <span class="eyebrow">Từ trong âm thanh</span>
        <div class="wp-word">${esc(w)}</div>
        ${rom ? `<div class="wp-rom">${esc(rom)}</div>` : ''}
      </div>
${WP_TOOLS}
    </div>
    <div class="wp-body">
      <p class="wp-gloss">${vi ? esc(vi) : 'Không có nghĩa kèm theo.'}</p>
      <p class="asst-note">Từ điển tích hợp chỉ có tiếng Hàn; đây là nghĩa nhanh do AI cung cấp.</p>
    </div>`;
  showPanel(el);
}

function autoGrow(ta){ ta.style.height = 'auto'; ta.style.height = Math.min(ta.scrollHeight, 160) + 'px'; }

function mountAssistant(){
  const A = state.assistant;
  if (A.tab === 'chat'){
    const ta = $('#asstInput');
    if (ta){
      autoGrow(ta);
      ta.addEventListener('input', () => autoGrow(ta));
      ta.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey){ e.preventDefault(); asstSend(); } });
      if (!A.busy) ta.focus();
    }
    const box = $('#asstMsgs'); if (box) box.scrollTop = box.scrollHeight;
  } else {
    const f = $('#asstFile');
    if (f) f.addEventListener('change', () => { if (f.files && f.files[0]) asstHandleFile(f.files[0]); });
  }
}

/* ---------- Labi: cửa sổ nổi kéo-thả (dùng chung engine kéo với bảng tra) ---------- */
function labiBody(){
  const A = state.assistant;
  return `
  <p class="asst-intro">Hỏi đáp nhanh về ngôn ngữ, hoặc tải lên một tệp âm thanh để AI nhận diện ngôn ngữ, tách câu–từ, tra nghĩa và dịch.</p>
  <div class="asst-tabs">
    <button class="asst-tab${A.tab === 'chat' ? ' on' : ''}" data-asst-tab="chat">💬 Hỏi đáp</button>
    <button class="asst-tab${A.tab === 'audio' ? ' on' : ''}" data-asst-tab="audio">🎧 Phân tích âm thanh</button>
  </div>
  ${A.tab === 'chat' ? asstChatTab() : asstAudioTab()}`;
}
function labiPanel(){
  let el = $('#labiPanel');
  if (!el){
    el = document.createElement('aside');
    el.id = 'labiPanel'; el.className = 'floatwin labi-win'; el.dataset.posKey = 'labiPos';
    el.setAttribute('aria-live', 'polite');
    document.body.appendChild(el);
  }
  return el;
}
function labiRender(){
  const el = $('#labiPanel');
  if (!el || !el.classList.contains('open')) return;
  el.innerHTML = `
    <div class="fw-head">
      <div class="fw-title"><span class="fw-dot">✦</span> Labi <span class="fw-sub">trợ lý ngôn ngữ</span></div>
      <div class="fw-tools">
        <button class="icon-btn" id="labiMin" title="Thu gọn / mở rộng"><svg viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg></button>
        <button class="icon-btn" id="labiClose" title="Đóng"><svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
      </div>
    </div>
    <div class="fw-body" id="labiBody">${labiBody()}</div>`;
  mountAssistant();
}
function showLabi(el){
  el.classList.toggle('collapsed', !!store.get('labiCollapsed', false));
  if (window.innerWidth >= WP_DESKTOP){
    const saved = store.get('labiPos', null);
    const pos = saved || { left: Math.max(8, window.innerWidth - 468), top: 72 };
    const c = clampPanel(el, pos.left, pos.top);
    el.style.left = c.left + 'px'; el.style.top = c.top + 'px';
    el.style.right = 'auto'; el.style.bottom = 'auto';
  } else {
    el.style.left = el.style.top = el.style.right = el.style.bottom = '';
  }
}
function openLabi(){
  const el = labiPanel();
  el.classList.add('open');
  labiRender();
  showLabi(el);
  state.labiOpen = true; updateLabiNav();
}
function closeLabi(){
  const el = $('#labiPanel'); if (el) el.classList.remove('open');
  state.labiOpen = false; updateLabiNav();
}
function toggleLabi(){ state.labiOpen ? closeLabi() : openLabi(); }
function updateLabiNav(){ const b = $('#labiNav'); if (b) b.setAttribute('aria-current', state.labiOpen ? 'true' : 'false'); }

function asstSend(text){
  const A = state.assistant;
  const ta = $('#asstInput');
  const msg = String(text != null ? text : (ta ? ta.value : '')).trim();
  if (!msg || A.busy) return;
  A.messages.push({ role:'user', content: msg });
  A.busy = true;
  labiRender();
  Translate.chat(A.messages, (reply, err) => {
    A.busy = false;
    A.messages.push({ role:'assistant', content: err ? ('Xin lỗi, mình chưa trả lời được. ' + asstErrMsg(err)) : (reply || '(không có nội dung)') });
    if (state.labiOpen) labiRender();
  });
}

function asstHandleFile(file){
  const A = state.assistant.audio;
  A.name = file.name;
  if (file.size > 15 * 1024 * 1024){
    A.error = 'Tệp quá lớn (' + Math.round(file.size / 1048576) + ' MB). Giới hạn khoảng 15 MB — hãy cắt ngắn đoạn âm thanh rồi thử lại.';
    A.result = null; A.busy = false; labiRender(); return;
  }
  A.error = null; A.result = null; A.busy = true;
  labiRender();
  const reader = new FileReader();
  reader.onload = () => {
    const dataUrl = String(reader.result || '');
    const comma = dataUrl.indexOf(',');
    const b64 = comma >= 0 ? dataUrl.slice(comma + 1) : dataUrl;
    Translate.analyzeAudio(b64, file.type || 'audio/mpeg', (res, err) => {
      A.busy = false;
      if (err || !res) A.error = asstErrMsg(err || 'no-server');
      else if (res.error) A.error = asstErrMsg(res.error);
      else {
        A.result = res; A.lang = res.lang || ''; A.error = null; A.editing = false; A.showVi = false;
        // câu có thể sửa được: mỗi câu = { ko, vi }
        A.segments = (res.sentences || []).map(s => ({
          ko: (s.text && s.text.trim()) ? s.text.trim()
              : (s.words || []).map(w => w.w).join(' '),
          vi: s.vi || ''
        })).filter(s => s.ko);
        // bản đồ nghĩa từng từ (để tra nhanh + nút thêm vào từ điển)
        A.glossMap = {};
        (res.sentences || []).forEach(s => (s.words || []).forEach(w => {
          if (w.w && !A.glossMap[w.w]) A.glossMap[w.w] = { rom: w.rom || '', vi: w.vi || '' };
        }));
      }
      if (state.labiOpen) labiRender();
    });
  };
  reader.onerror = () => { A.busy = false; A.error = 'Không đọc được tệp âm thanh.'; labiRender(); };
  reader.readAsDataURL(file);
}

/* Từ điển tự bồi: thêm từ (nghĩa do AI đọc từ âm thanh), lưu trong trình duyệt và làm giàu kho tra. */
function addUserWord(ko, rom, vi){
  ko = String(ko || '').trim(); if (!ko || !vi) return;
  const entry = { ko: ko, rom: String(rom || ''), vi: String(vi), pos: 'từ tự thêm' };
  if (window.Words && Words.addDict) Words.addDict([entry]);
  const ud = store.get('userdict', []) || [];
  if (!ud.some(x => x.ko === ko)){ ud.push(entry); store.set('userdict', ud); }
}
function loadUserDict(){
  const ud = store.get('userdict', []) || [];
  if (ud.length && window.Words && Words.addDict) Words.addDict(ud);
}

/* Áp dụng cách ngắt câu mới người dùng vừa sửa, rồi dịch lại các câu chưa có bản dịch. */
function asstApplyEdit(){
  const A = state.assistant.audio;
  const box = $('#asstEditBox');
  if (!box) return;
  const lines = box.value.split('\n').map(s => s.trim()).filter(Boolean);
  if (!lines.length) return;
  const oldVi = {}; (A.segments || []).forEach(s => { oldVi[s.ko] = s.vi; });
  A.segments = lines.map(ko => ({ ko: ko, vi: oldVi[ko] || '' }));
  A.editing = false;
  const need = A.segments.filter(s => !s.vi).map(s => s.ko);
  if (need.length && window.Translate && Translate.run){
    A.retranslating = true; labiRender();
    Translate.run(need, (map) => {
      A.retranslating = false;
      if (map) A.segments.forEach(s => { if (!s.vi) s.vi = map[Translate.hash(s.ko)] || s.vi; });
      A.showVi = true;
      if (state.labiOpen) labiRender();
    });
  } else {
    labiRender();
  }
}

/* ============================================================
   BÀI TẬP — sinh câu hỏi từ dữ liệu khoá học
   ============================================================ */
const QUIZ_TYPES = [
  ['mix','Trộn'], ['meaning','Chọn nghĩa'], ['word','Chọn từ'],
  ['listen','Nghe hiểu'], ['fill','Điền vào câu'], ['order','Sắp xếp câu']
];
const QUIZ_KINDS = ['meaning','word','listen','fill','order'];
const QUIZ_ROUND = 10;

let quizData = null;
function quizPool(){
  if (quizData) return quizData;
  const seen = {}, vocab = [], sents = [];
  curLessons().forEach(l => {
    (l.vocab || []).forEach(v => {
      if (v.ko && v.vi && !seen[v.ko]){ seen[v.ko] = 1; vocab.push({ ko:v.ko, rom:v.rom, vi:v.vi, lesson:l.no }); }
    });
    (l.dialogue || []).forEach(d => { if (d.ko && d.vi) sents.push({ ko:d.ko, vi:d.vi, lesson:l.no }); });
    (l.grammar  || []).forEach(g => { if (g.ex && g.ex.ko && g.ex.vi) sents.push({ ko:g.ex.ko, vi:g.ex.vi, lesson:l.no }); });
  });
  quizData = { vocab, sents };
  return quizData;
}

const _qrnd = n => Math.floor(Math.random() * n);
const _qpick = a => a[_qrnd(a.length)];
function _qsample(a, n){ a = a.slice(); const out = []; while (out.length < n && a.length) out.push(a.splice(_qrnd(a.length), 1)[0]); return out; }
function _qshuffle(a){ a = a.slice(); for (let i = a.length - 1; i > 0; i--){ const j = _qrnd(i + 1); const x = a[i]; a[i] = a[j]; a[j] = x; } return a; }

function makeQuestion(type, depth){
  depth = depth || 0;
  const P = quizPool();
  if (!P.vocab.length || depth > 4) return null;
  let kind = type === 'mix' ? _qpick(QUIZ_KINDS) : type;
  if ((kind === 'fill' || kind === 'order') && P.sents.length < 3) kind = 'meaning';

  if (kind === 'meaning' || kind === 'listen'){
    const w = _qpick(P.vocab);
    const distr = _qsample(P.vocab.filter(x => x.vi !== w.vi), 3).map(x => x.vi);
    if (distr.length < 3) return makeQuestion('word', depth + 1);
    const options = _qshuffle([w.vi].concat(distr));
    return { kind, ko:w.ko, rom:w.rom, hideStem: kind === 'listen',
             prompt: kind === 'listen' ? 'Nghe rồi chọn nghĩa đúng' : 'Từ này nghĩa là gì?',
             options, correct: options.indexOf(w.vi),
             explain: (kind === 'listen' ? 'Câu đọc là « ' + w.ko + ' »' : '« ' + w.ko + ' »') + ' nghĩa là « ' + w.vi + ' ».' };
  }
  if (kind === 'word'){
    const w = _qpick(P.vocab);
    const distr = _qsample(P.vocab.filter(x => x.ko !== w.ko), 3).map(x => x.ko);
    if (distr.length < 3) return makeQuestion('meaning', depth + 1);
    const options = _qshuffle([w.ko].concat(distr));
    return { kind, vi:w.vi, prompt:'Chọn từ tiếng Hàn đúng', koOpts:true,
             options, correct: options.indexOf(w.ko),
             explain: '« ' + w.vi + ' » trong tiếng Hàn là « ' + w.ko + ' ».' };
  }
  if (kind === 'fill'){
    for (const s of _qshuffle(P.sents)){
      const toks = s.ko.split(/\s+/);
      for (let i = 0; i < toks.length; i++){
        const bare = toks[i].replace(/[.,?!~]/g, '');
        const w = P.vocab.find(v => v.ko === bare);
        if (w){
          const distr = _qsample(P.vocab.filter(x => x.ko !== w.ko), 3).map(x => x.ko);
          if (distr.length < 3) return makeQuestion('meaning', depth + 1);
          const options = _qshuffle([w.ko].concat(distr));
          const stem = toks.map((t, k) => k === i ? '____' : t).join(' ');
          return { kind, stem, hint:s.vi, koOpts:true, options, correct: options.indexOf(w.ko),
                   explain: 'Từ đúng điền vào là « ' + w.ko + ' » (' + w.vi + '). Câu đầy đủ: ' + s.ko };
        }
      }
    }
    return makeQuestion('meaning', depth + 1);
  }
  if (kind === 'order'){
    const cand = _qshuffle(P.sents).find(s => { const n = s.ko.split(/\s+/).length; return n >= 3 && n <= 6; });
    if (!cand) return makeQuestion('meaning', depth + 1);
    const tokens = cand.ko.split(/\s+/);
    return { kind, tokens, hint:cand.vi, chips: _qshuffle(tokens.map((t, id) => ({ t, id }))), order: [],
             explain: 'Trật tự đúng: ' + tokens.join(' ') + (cand.vi ? ' (' + cand.vi + ')' : '') };
  }
  return null;
}

function quizStart(type){
  type = type || 'mix';
  const qs = [];
  let guard = 0;
  while (qs.length < QUIZ_ROUND && guard++ < 80){ const q = makeQuestion(type); if (q){ q.chosen = null; q.checked = false; qs.push(q); } }
  state.quiz = { type, qs, idx:0 };
}

function paintQuiz(){ const a = $('#quizArea'); if (a) a.innerHTML = quizCard(); }

function quizCorrect(q){
  if (q.kind === 'order'){
    if (q.order.length !== q.tokens.length) return false;
    return q.order.map(id => q.chips.find(x => x.id === id).t).join(' ') === q.tokens.join(' ');
  }
  return q.chosen === q.correct;
}
function quizScore(){ return state.quiz.qs.reduce((n, q) => n + (quizCorrect(q) ? 1 : 0), 0); }

function quizNav(){
  const Q = state.quiz, q = Q.qs[Q.idx], last = Q.idx + 1 >= Q.qs.length;
  return `<div class="q-nav">
      <button class="pbtn" data-quiz-prev="1"${Q.idx === 0 ? ' disabled' : ''}>← Câu trước</button>
      ${q.checked ? '' : '<button class="pbtn" data-quiz-check="1">Kiểm tra đáp án</button>'}
      <button class="pbtn primary" data-quiz-next="1">${last ? 'Xem kết quả →' : 'Câu sau →'}</button>
    </div>`;
}

function quizCard(){
  const Q = state.quiz;
  if (!Q || !Q.qs || !Q.qs.length) return '<div class="quiz-card"><p class="wp-empty">Chưa tạo được câu hỏi.</p></div>';
  if (Q.idx >= Q.qs.length) return quizSummary();
  const q = Q.qs[Q.idx];
  const done = Q.qs.filter(x => x.checked).length;
  const dots = Q.qs.map((x, k) => `<i class="${k === Q.idx ? 'now' : (x.checked ? 'done' : '')}"></i>`).join('');
  const top = `<div class="quiz-top">
      <span class="eyebrow">Câu ${Q.idx + 1} / ${Q.qs.length}</span>
      <div class="dots">${dots}</div>
      <span class="quiz-score">Đã kiểm tra ${done}/${Q.qs.length}</span>
    </div>`;

  let body;
  if (q.kind === 'order'){
    body = quizOrder(q);
  } else {
    let stem;
    if (q.kind === 'word') stem = `<p class="q-stem q-vi">${esc(q.vi)}</p>`;
    else if (q.kind === 'fill') stem = `<p class="q-stem ko">${esc(q.stem).replace('____', '<span class="blank">____</span>')}</p>`;
    else if (q.hideStem) stem = `<div class="q-listen-wrap"><button class="pbtn primary" data-quiz-say="${esc(q.ko)}"><svg viewBox="0 0 24 24"><polygon points="6 4 20 12 6 20 6 4"></polygon></svg> Nghe từ</button></div>`;
    else stem = `<p class="q-stem ko">${esc(q.ko)}${q.rom ? ` <span class="q-rom">[${esc(q.rom)}]</span>` : ''}</p>`;
    const prompt = q.prompt ? `<p class="q-prompt">${esc(q.prompt)}</p>` : '';
    const hint = q.hint ? `<p class="q-hint">${esc(q.hint)}</p>` : '';
    const opts = `<div class="opts" id="opts">${q.options.map((o, k) => {
        let cls = 'opt' + (q.koOpts ? ' ko' : '');
        if (q.checked){ if (k === q.correct) cls += ' ok'; else if (k === q.chosen) cls += ' no'; }
        else if (k === q.chosen) cls += ' sel';
        return `<button class="${cls}" data-quiz-opt="${k}"${q.checked ? ' disabled' : ''}>${esc(o)}</button>`;
      }).join('')}</div>`;
    body = stem + prompt + hint + opts;
  }
  const fb = q.checked ? quizFeedback(q) : '';
  return `<div class="quiz-card">${top}${body}${fb}${quizNav()}</div>`;
}

function quizFeedback(q){
  const right = quizCorrect(q);
  const ans = q.kind === 'order' ? q.tokens.join(' ') : q.options[q.correct];
  const ansCls = q.kind === 'order' ? ' ko' : '';
  const noChoice = q.kind === 'order' ? !q.order.length : (q.chosen === null || q.chosen === undefined);
  return `<div class="fb show" style="background:${right ? 'var(--ok-soft)' : 'var(--seal-soft)'}">
      <b>${right ? 'Chính xác 👍' : (noChoice ? 'Chưa chọn đáp án.' : 'Chưa đúng.')}</b>
      ${right ? '' : `Đáp án đúng: <b class="${ansCls}">${esc(ans)}</b>.`}
      ${q.explain ? `<div class="q-explain"><b>Vì sao:</b> ${esc(q.explain)}</div>` : ''}
    </div>`;
}

function quizOrder(q){
  const chosen = q.order.map(id => { const c = q.chips.find(x => x.id === id); return `<button class="ochip"${q.checked ? ' disabled' : ` data-quiz-orm="${id}"`}>${esc(c.t)}</button>`; }).join('');
  const remain = q.chips.filter(x => q.order.indexOf(x.id) < 0).map(x => `<button class="ochip pool" data-quiz-oadd="${x.id}">${esc(x.t)}</button>`).join('');
  const tools = q.checked ? '' : `<div class="q-order-tools"><button class="mini" data-quiz-oclear="1"${q.order.length ? '' : ' disabled'}>Xoá hết</button></div>`;
  return `<p class="q-prompt">Sắp xếp các mảnh thành câu đúng</p><p class="q-hint">${esc(q.hint)}</p>
    <div class="obuild">${chosen || '<span class="obuild-ph">Bấm các mảnh bên dưới để ghép câu…</span>'}</div>
    ${q.checked ? '' : `<div class="opool">${remain}</div>`}${tools}`;
}

function quizSummary(){
  const Q = state.quiz, score = quizScore(), pct = Math.round(score / Q.qs.length * 100);
  const msg = pct >= 80 ? 'Xuất sắc! 🎉' : pct >= 50 ? 'Khá tốt — luyện thêm chút nữa nhé.' : 'Cứ luyện tiếp, nhớ dần thôi.';
  return `<div class="quiz-card quiz-done">
      <div class="qd-score">${score}<span>/ ${Q.qs.length}</span></div>
      <p class="qd-msg">${msg}</p>
      <div class="q-nav" style="justify-content:center">
        <button class="pbtn" data-quiz-review="1">Xem lại các câu</button>
        <button class="pbtn primary" data-quiz-restart="1">Làm lại 10 câu</button>
      </div>
    </div>`;
}

/* ============================================================
   ĐIỀU HƯỚNG & GẮN SỰ KIỆN
   ============================================================ */

const CRUMBS = {
  home:'Khoá học', lesson:'Bài học', write:'Tập viết',
  srs:'Ôn tập', dict:'Từ điển', quiz:'Bài tập', shadow:'Luyện shadowing',
  numbers:'Số đếm', topik:'Thi thử TOPIK', about:'Giới thiệu', facts:'Bạn có biết?'
};

function render(){
  const view = $('#view');
  view.innerHTML = VIEWS[state.view]();
  view.classList.toggle('wide', state.view === 'write');

  const KO_VIEWS = ['home','lesson','write','shadow','srs','dict','quiz','numbers','topik'];
  $$('.nav-main [data-go]').forEach(b => {
    const on = b.dataset.go === state.view || (state.view === 'lesson' && b.dataset.go === 'home');
    b.setAttribute('aria-current', on ? 'page' : 'false');
  });
  const isZh = state.view.indexOf('zh_') === 0, isRu = state.view.indexOf('ru_') === 0, isJa = state.view.indexOf('ja_') === 0, isEn = state.view.indexOf('en_') === 0;
  document.documentElement.setAttribute('data-lang', isZh ? 'zh' : isRu ? 'ru' : isJa ? 'ja' : isEn ? 'en' : 'ko');   // tông màu theo ngôn ngữ
  if (typeof syncThemeColor === 'function') syncThemeColor();
  const koDrop = $('#koDrop');
  if (koDrop) koDrop.classList.toggle('active', KO_VIEWS.includes(state.view));
  const zhDrop = $('#zhDrop');
  if (zhDrop) zhDrop.classList.toggle('active', isZh);
  const ruDrop = $('#ruDrop');
  if (ruDrop) ruDrop.classList.toggle('active', isRu);
  const jaDrop = $('#jaDrop');
  if (jaDrop) jaDrop.classList.toggle('active', isJa);
  const enDrop = $('#enDrop');
  if (enDrop) enDrop.classList.toggle('active', isEn);
  const tq = $('#topq');
  if (tq) tq.placeholder = isZh ? 'Tra nhanh tiếng Trung (chữ Hán / pinyin / nghĩa)…' : isRu ? 'Tra nhanh tiếng Nga (không cần dấu trọng âm)…' : isJa ? 'Tra nhanh tiếng Nhật (kana / kanji / romaji / nghĩa)…' : isEn ? 'Tra nhanh tiếng Anh (từ / phiên âm / nghĩa)…' : state.view === 'about' ? 'Tra nhanh: 한국어 · 中文 · русский · tiếng Việt…' : 'Tra nhanh tiếng Hàn (Hangul / romaja / nghĩa)…';
  $$('.nav-drop.open').forEach(d => {
    d.classList.remove('open');
    const bb = d.querySelector('.nav-drop-btn'); if (bb) bb.setAttribute('aria-expanded', 'false');
  });
  updateLabiNav();

  const l = state.lesson && curLesson();
  $('#crumb').innerHTML = isZh
    ? zhCrumb()
    : isRu
    ? ruCrumb()
    : isJa
    ? jaCrumb()
    : isEn
    ? enCrumb()
    : state.view === 'about'
    ? `<b>Giới thiệu LangLab</b>`
    : state.view === 'lesson' && l
    ? `<button class="crumb-link" data-go="home">Tiếng Hàn</button> <span>›</span> <button class="crumb-link" data-go="home">Sơ cấp 1</button> <span>›</span> <b>Bài ${String(l.no).padStart(2,'0')} · ${esc(l.vi)}</b>`
    : `<button class="crumb-link" data-go="home">Tiếng Hàn</button> <span>›</span> <b>${CRUMBS[state.view]}</b>`;

  if (isZh || isJa) (window.requestAnimationFrame ? requestAnimationFrame : (f => setTimeout(f, 16)))(zhMount);
  if (state.view === 'ru_write') (window.requestAnimationFrame ? requestAnimationFrame : (f => setTimeout(f, 16)))(ruTraceMount);
  if ((state.view === 'zh_exam' || state.view === 'ru_exam' || state.view === 'ja_exam') && exCtx().st.exam && exCtx().st.exam.phase === 'doing') hskMount(); else hskStop();
  if (state.view === 'write') mountWrite();
  if (state.view === 'dict'){ mountDict(); loadDict(added => { if (added && state.view === 'dict') render(); }); }
  if (state.view === 'shadow'){
    const box = $('#shInput');
    if (box && state.shadow.raw) box.value = state.shadow.raw;
  }
  if (state.view === 'lesson' && state.tab === 'write') mountTrace();
  if (state.view === 'topik' && state.topik && state.topik.phase === 'doing') mountTopik(); else topikStopTimer();
  window.scrollTo({ top:0, behavior:'instant' in window ? 'instant' : 'auto' });
  if (typeof factSchedule === 'function') factSchedule();
}

/* ============================================================
   TIẾNG TRUNG (中文) — nền tảng (nét · bộ thủ · pinyin) + khoá HSK 1–5 (106 bài)
   Dữ liệu: course-zh.js · thứ tự nét: Hanzi Writer + HANZI_DATA
   (Make Me a Hanzi, giấy phép Arphic Public License).
   ============================================================ */
const _ZC = (typeof COURSE_ZH   !== 'undefined') ? COURSE_ZH   : { levels:[], lessons:[] };
const _ZS = (typeof STROKES_ZH  !== 'undefined') ? STROKES_ZH  : [];
const _ZR = (typeof RADICALS_ZH !== 'undefined') ? RADICALS_ZH : [];
const _ZP = (typeof PINYIN_ZH   !== 'undefined') ? PINYIN_ZH   : { tones:[], initials:[], finals:[], notes:[] };

const ZH_LOOKUP = (function(){
  const m = {};
  _ZC.lessons.forEach(l => l.vocab.forEach(w => {
    const lv = l.level || 'hsk1';
    if (!m[w.zh]) m[w.zh] = Object.assign({ lessons:[], refs:[], levels:[] }, w);
    const e = m[w.zh];
    if (e.lessons.indexOf(l.no) < 0) e.lessons.push(l.no);
    if (!e.refs.some(r => r.lv === lv && r.no === l.no)) e.refs.push({ lv, no:l.no });
    if (e.levels.indexOf(lv) < 0) e.levels.push(lv);
  }));
  return m;
})();
/* Tên ngắn của cấp: hsk3 → "HSK 3" */
function zhLevelName(id){ const v = _ZC.levels.find(x => x.id === id); return v ? v.zh : (id || '').toUpperCase(); }
/* Cấp dùng cho Ôn tập / Bài tập / Thi thử (mặc định theo cấp khoá học); 'all' = mọi cấp */
function zhPracLevel(){
  const ids = _ZC.levels.filter(v => v.status === 'active').map(v => v.id);
  const cur = state.zh.pracLevel || state.zh.level;
  return cur === 'all' ? 'all' : (ids.indexOf(cur) >= 0 ? cur : (ids[0] || 'hsk1'));
}
function zhPool(level){
  const all = Object.values(ZH_LOOKUP);
  if (!level || level === 'all') return all;
  const p = all.filter(w => w.levels.indexOf(level) >= 0);
  return p.length >= 12 ? p : all;
}
function zhLevelChips(attr, cur, withAll){
  const act = _ZC.levels.filter(v => v.status === 'active');
  return `<div class="level-strip compact">${act.map(v => `<button class="level-chip" ${attr}="${v.id}"${cur === v.id ? ' aria-pressed="true"' : ''}>${esc(v.zh)}</button>`).join('')}${withAll ? `<button class="level-chip" ${attr}="all"${cur === 'all' ? ' aria-pressed="true"' : ''}>Tất cả</button>` : ''}</div>`;
}

function getCssVar(v){ try { return getComputedStyle(document.body).getPropertyValue(v).trim(); } catch(e){ return ''; } }
function hasHanzi(ch){ return /[一-鿿぀-ヿ]/.test(ch || ''); }
/* Dữ liệu nét tiếng Nhật (kana + kanji, gói hanzi-writer-data-jp): hanzi-jp/<codepoint>.json */
function jaLoadChar(c){
  const D = window.HANZI_JP || (window.HANZI_JP = {});
  if (D[c]) return Promise.resolve(D[c]);
  if (typeof fetch !== 'function') return Promise.reject(new Error('no fetch'));
  return fetch('hanzi-jp/' + c.codePointAt(0).toString(16) + '.json')
    .then(r => { if (!r.ok) throw new Error('404'); return r.json(); })
    .then(d => { D[c] = d; return d; });
}
/* Dữ liệu nét: có sẵn trong bundle (HSK1–2) thì dùng ngay, không thì tải hanzi/<codepoint>.json theo nhu cầu */
function zhLoadChar(c){
  const D = window.HANZI_DATA || (window.HANZI_DATA = {});
  if (D[c]) return Promise.resolve(D[c]);
  if (typeof fetch !== 'function') return Promise.reject(new Error('no fetch'));
  return fetch('hanzi/' + c.codePointAt(0).toString(16) + '.json')
    .then(r => { if (!r.ok) throw new Error('404'); return r.json(); })
    .then(d => { D[c] = d; return d; });
}
function zhSpeak(text){
  try {
    const synth = window.speechSynthesis; if (!synth){ toast('Trình duyệt chưa hỗ trợ phát âm'); return; }
    let done = false;
    const speak = () => {
      if (done) return; done = true;
      synth.cancel();
      const u = new SpeechSynthesisUtterance(text);
      u.lang = 'zh-CN'; u.rate = 0.8;
      const vs = synth.getVoices() || [];
      const zh = vs.find(v => /(^zh\b|zh[-_]|chinese|中文|普通话|mandarin)/i.test((v.lang || '') + ' ' + (v.name || '')));
      if (zh) u.voice = zh;
      else if (!zhSpeak._warned && !vs.some(v => /^zh/i.test(v.lang || ''))){ zhSpeak._warned = true; toast('Máy chưa có giọng đọc tiếng Trung — cài gói giọng zh-CN để nghe rõ thanh điệu.'); }
      synth.speak(u);
    };
    const vs = synth.getVoices() || [];
    if (vs.length) speak();                                   // đã có danh sách giọng → đọc ngay
    else { try { synth.addEventListener('voiceschanged', speak, { once:true }); } catch(e){} setTimeout(speak, 300); }
  } catch(e){}
}
function zhLevel(){ return _ZC.levels.find(x => x.id === state.zh.level) || _ZC.levels[0] || { vi:'HSK 1', zh:'HSK 1' }; }
function zhLessonList(){ return _ZC.lessons.filter(l => l.level === state.zh.level); }
function zhCurLesson(){ return _ZC.lessons.find(l => l.no === state.zh.lesson && l.level === state.zh.level); }
function zhWriteChars(level){
  const set = [];
  const push = c => { if (c && hasHanzi(c) && set.indexOf(c) < 0) set.push(c); };
  if (!level || level === 'hsk1') _ZS.forEach(s => push(s.ex));   // chữ mẫu của 8 nét đi cùng HSK1
  _ZC.lessons.forEach(l => { if (!level || l.level === level) l.vocab.forEach(w => { for (const c of w.zh) push(c); }); });
  return set;
}
/* Cấp đang chọn trong Tập viết: mặc định theo cấp khoá học */
function zhWriteLevel(){
  const ids = _ZC.levels.filter(v => v.status === 'active').map(v => v.id);
  const cur = state.zh.writeLevel || state.zh.level;
  return ids.indexOf(cur) >= 0 ? cur : (ids[0] || 'hsk1');
}
function zhCrumb(){
  const map = { zh_home:'Khoá học', zh_strokes:'Các nét', zh_radicals:'Bộ thủ',
    zh_pinyin:'Pinyin & thanh điệu', zh_write:'Tập viết', zh_dict:'Từ điển', zh_srs:'Ôn tập',
    zh_quiz:'Bài tập', zh_exam:'Thi thử HSK' };
  const L = zhCurLesson();
  if (state.view === 'zh_lesson' && L)
    return `<button class="crumb-link" data-go="zh_home">Tiếng Trung</button> <span>›</span> <button class="crumb-link" data-go="zh_home">${esc(zhLevel().zh)}</button> <span>›</span> <b>Bài ${String(L.no).padStart(2,'0')} · ${esc(L.vi)}</b>`;
  return `<button class="crumb-link" data-go="zh_home">Tiếng Trung</button> <span>›</span> <b>${esc(map[state.view] || '')}</b>`;
}
function zhTokens(str){
  let out = '';
  for (const ch of (str || '')) out += /[一-鿿]/.test(ch) ? `<span class="zc" data-zc="${esc(ch)}">${esc(ch)}</span>` : esc(ch);
  return out;
}

/* ---------------- Views tiếng Trung ---------------- */
VIEWS.zh_home = function(){
  const lv = zhLevel(), L = zhLessonList(), total = lv.lessons || 15;
  const cards = [
    ['zh_strokes','Các nét','8 nét cơ bản của chữ Hán','⼂'],
    ['zh_radicals','Bộ thủ','Bộ thường gặp + Hán–Việt','部'],
    ['zh_pinyin','Pinyin & thanh điệu','Ghép âm và 4 thanh','声'],
    ['zh_write','Tập viết','Xem thứ tự nét & luyện tô','写']
  ];
  return `
  <div class="page-head">
    <span class="eyebrow">Khoá tiếng Trung · ${esc(lv.zh)}</span>
    <h1>Bắt đầu tiếng Trung từ nét chữ tới câu</h1>
    <p>Học nền tảng (nét · bộ thủ · pinyin) rồi vào bài theo khung <em>Giáo trình chuẩn HSK</em>. Hiện có ${L.length}/${total} bài của ${esc(lv.zh)}${lv.vi && lv.vi.indexOf('·') > 0 ? ' · ' + esc(lv.vi.split('·')[1].trim()) : ''}.</p>
  </div>
  <div class="zh-found">
    ${cards.map(c => `<button class="zh-found-card" data-go="${c[0]}"><span class="zh-found-ico ko">${c[3]}</span><span class="zh-found-tx"><b>${c[1]}</b><i>${c[2]}</i></span></button>`).join('')}
  </div>
  <div class="level-strip">
    ${_ZC.levels.map(v => {
      const active = v.status === 'active';
      return `<button class="level-chip" data-zh-level="${v.id}"${state.zh.level === v.id ? ' aria-pressed="true"' : ''}${active ? '' : ' disabled'} title="${active ? '' : 'Đang biên soạn'}">${esc(v.vi)} <span class="lv-ko">${esc(v.zh)}</span>${active ? '' : ' <span class="lv-soon">sắp có</span>'}</button>`;
    }).join('')}
  </div>
  <div class="lesson-grid">
    ${L.map(l => `
      <button class="lesson-card" data-zh-lesson="${l.no}">
        <span class="lesson-no"><i></i> BÀI ${String(l.no).padStart(2,'0')}</span>
        <h3 class="ko">${esc(l.zh)}</h3>
        <p class="vi"><span class="py">${esc(l.pinyin)}</span> · ${esc(l.vi)}</p>
        <span class="lesson-meta">${l.vocab.length} từ · ${l.grammar.length} điểm ngữ pháp</span>
      </button>`).join('')}
    ${Array.from({ length: total - L.length }, (_, i) => `<div class="lesson-card soon"><span class="lesson-no"><i></i> BÀI ${String(L.length + i + 1).padStart(2,'0')}</span><h3 class="ko">·····</h3><p class="vi">sắp có</p></div>`).join('')}
  </div>`;
};

VIEWS.zh_strokes = function(){
  return `
  <div class="page-head">
    <span class="eyebrow">Tiếng Trung · Nền tảng</span>
    <h1>8 nét cơ bản</h1>
    <p>Mọi chữ Hán đều ghép từ vài nét cơ bản. Nắm tên và hướng viết trước khi tập viết chữ. Bấm ô chữ mẫu để xem lại animation.</p>
  </div>
  <div class="zh-stroke-grid">
    ${_ZS.map(s => `
      <div class="zh-stroke-card">
        <div class="zh-stroke-glyph">${esc(s.stroke)}</div>
        <div class="zh-stroke-body">
          <div class="zh-stroke-name"><b class="ko">${esc(s.name)}</b> <span class="py">${esc(s.pinyin)}</span></div>
          <div class="zh-stroke-vi">${esc(s.vi)} · <i>${esc(s.hv)}</i></div>
          <p class="zh-stroke-desc">${esc(s.desc)}</p>
        </div>
        <div class="zh-stroke-ex">
          <div class="hz" data-hz="${esc(s.ex)}" data-size="84"></div>
          <span class="zh-ex-label ko">${esc(s.ex)}</span>
        </div>
      </div>`).join('')}
  </div>`;
};

VIEWS.zh_radicals = function(){
  return `
  <div class="page-head">
    <span class="eyebrow">Tiếng Trung · Nền tảng</span>
    <h1>Bộ thủ thường gặp</h1>
    <p>Bộ thủ là “thành phần gốc” gợi nghĩa của chữ Hán và là cách tra từ điển. Dưới đây là ${_ZR.length} bộ hay gặp, kèm âm Hán–Việt và chữ ví dụ (bấm để tra).</p>
  </div>
  <div class="zh-rad-grid">
    ${_ZR.map(r => `
      <div class="zh-rad-card">
        <div class="zh-rad-head"><span class="zh-rad-char ko">${esc(r.rad)}</span>${r.alt ? `<span class="zh-rad-alt ko">${esc(r.alt)}</span>` : ''}</div>
        <div class="zh-rad-info">
          <div><b>${esc(r.hv)}</b> <span class="py">${esc(r.pinyin)}</span></div>
          <div class="zh-rad-vi">${esc(r.vi)}</div>
          <div class="zh-rad-ex">${(r.ex || []).map(c => `<span class="zc" data-zc="${esc(c)}">${esc(c)}</span>`).join('')}</div>
        </div>
      </div>`).join('')}
  </div>`;
};

VIEWS.zh_pinyin = function(){
  return `
  <div class="page-head">
    <span class="eyebrow">Tiếng Trung · Nền tảng</span>
    <h1>Pinyin &amp; thanh điệu</h1>
    <p><b>Pinyin</b> (拼音 — Hán ngữ bính âm) là cách phiên âm chính thức của tiếng Phổ thông bằng chữ Latinh. Mỗi âm tiết = <b>phụ âm đầu + vần + thanh điệu</b> — ví dụ <span class="py">nǐ</span> = n + i + thanh 3. Mỗi âm tiết mang một trong 4 thanh (hoặc thanh nhẹ); đọc sai thanh là sai nghĩa.</p>
  </div>
  <div class="zh-tone-row">
    ${_ZP.tones.map(t => `
      <div class="zh-tone-card t${t.no}">
        <div class="zh-tone-syl">${esc(t.ex)}</div>
        <div class="zh-tone-hz ko">${esc(t.hz)}</div>
        <div class="zh-tone-name">${esc(t.name)}</div>
        <div class="zh-tone-vi">${esc(t.vi)}</div>
        <p class="zh-tone-desc">${esc(t.desc)}</p>
        <button class="pbtn mini" data-zh-speak="${esc(t.hz)}">🔊 Nghe</button>
      </div>`).join('')}
  </div>
  <div class="zh-py-cols">
    <section class="zh-py-sec"><h2>Phụ âm đầu (声母)</h2><div class="zh-py-chips">${_ZP.initials.map(x => `<span class="zh-py-chip">${esc(x)}</span>`).join('')}</div></section>
    <section class="zh-py-sec"><h2>Vần (韵母)</h2><div class="zh-py-chips">${_ZP.finals.map(x => `<span class="zh-py-chip">${esc(x)}</span>`).join('')}</div></section>
  </div>
  <section class="zh-py-sec"><h2>Lưu ý</h2><ul class="about-feats">${_ZP.notes.map(n => `<li>${esc(n)}</li>`).join('')}</ul></section>`;
};

VIEWS.zh_lesson = function(){
  const L = zhCurLesson();
  if (!L) return `<div class="page-head"><h1>Chưa chọn bài</h1><p>Quay lại <button class="crumb-link" data-go="zh_home">danh sách bài</button>.</p></div>`;
  const chars = [];
  L.vocab.forEach(w => { for (const c of w.zh) if (hasHanzi(c) && chars.indexOf(c) < 0) chars.push(c); });
  return `
  <article class="zh-lesson">
    <header class="zh-les-head">
      <div class="zh-les-title ko">${esc(L.zh)}</div>
      <div class="zh-les-sub"><span class="py">${esc(L.pinyin)}</span> · ${esc(L.vi)}</div>
      <p class="zh-les-skill">${esc(L.skill)}</p>
    </header>
    <section class="zh-sec">
      <h2>Ngữ pháp</h2>
      ${L.grammar.map(g => `
        <div class="zh-gram">
          <div class="zh-gram-form ko">${esc(g.form)} <span class="zh-gram-vi">— ${esc(g.vi)}</span></div>
          <p class="zh-gram-note">${esc(g.note)}</p>
          <div class="zh-gram-ex"><span class="ko">${zhTokens(g.ex.zh)}</span> <button class="icon-btn" data-zh-speak="${esc(g.ex.zh)}" title="Nghe">🔊</button><div class="zh-ex-py py">${esc(g.ex.pinyin)}</div><div class="zh-ex-vi">${esc(g.ex.vi)}</div></div>
        </div>`).join('')}
    </section>
    <section class="zh-sec">
      <h2>Từ vựng <span class="zh-count">${L.vocab.length}</span></h2>
      <div class="zh-vocab">
        ${L.vocab.map(w => `
          <div class="zh-word">
            <div class="zh-word-hz ko" data-zc="${esc(w.zh)}">${esc(w.zh)}</div>
            <div class="zh-word-mid">
              <div class="zh-word-py py">${esc(w.pinyin)}</div>
              <div class="zh-word-vi">${esc(w.vi)}</div>
              <div class="zh-word-meta"><span class="zh-hv">${esc(w.hv)}</span> · ${esc(w.pos)}</div>
            </div>
            <div class="zh-word-act">
              <button class="icon-btn" data-zh-speak="${esc(w.zh)}" title="Nghe">🔊</button>
              <button class="icon-btn" data-zh-write="${esc(w.zh[0])}" title="Tập viết">✎</button>
            </div>
          </div>`).join('')}
      </div>
    </section>
    <section class="zh-sec">
      <h2>Hội thoại</h2>
      <div class="zh-dia">
        ${L.dialogue.map(d => `
          <div class="zh-line">
            <span class="zh-sp">${esc(d.sp)}</span>
            <div class="zh-line-body">
              <div class="zh-line-zh ko">${zhTokens(d.zh)} <button class="icon-btn" data-zh-speak="${esc(d.zh)}" title="Nghe">🔊</button></div>
              <div class="zh-line-py py">${esc(d.pinyin)}</div>
              <div class="zh-line-vi">${esc(d.vi)}</div>
            </div>
          </div>`).join('')}
      </div>
    </section>
    <div class="stage-ctrl">
      <button class="pbtn primary" data-zh-write="${esc(chars[0] || '你')}">✎ Luyện viết chữ trong bài</button>
      <button class="pbtn" data-go="zh_home">← Về danh sách bài</button>
    </div>
  </article>`;
};

VIEWS.zh_write = function(){
  const wl = zhWriteLevel(), chars = zhWriteChars(wl);
  const cur = (state.zh.writeChar && hasHanzi(state.zh.writeChar)) ? state.zh.writeChar : (chars[0] || '你');
  const info = ZH_LOOKUP[cur];
  return `
  <div class="page-head">
    <span class="eyebrow">Tiếng Trung · Nền tảng</span>
    <h1>Tập viết — thứ tự nét</h1>
    <p>Bấm <b>Xem thứ tự nét</b> để xem chữ được viết ra sao, rồi <b>Luyện viết</b> để tự tô theo. Chọn chữ khác ở dưới.</p>
  </div>
  <div class="zh-write">
    <div class="zh-write-stage">
      <div class="hz-big"><div class="hz" id="hzBig" data-hz="${esc(cur)}" data-size="248" data-mode="write"></div></div>
      <div class="zh-write-side">
        <div class="zh-write-char ko">${esc(cur)}</div>
        <div class="zh-write-meta">${
          info
            ? `<span class="py">${esc(info.pinyin)}</span> · <b>${esc(info.hv)}</b><div class="zh-write-vi">${esc(info.vi)}</div>`
            : (function(){ const w = Object.values(ZH_LOOKUP).find(x => x.zh.indexOf(cur) >= 0); return w
                ? `<span class="zh-write-vi">Chữ trong từ <b class="ko">${esc(w.zh)}</b> · <span class="py">${esc(w.pinyin)}</span> · ${esc(w.vi)}</span>`
                : `<span class="zh-write-vi">Chữ lẻ — luyện thứ tự nét.</span>`; })()
        }</div>
        <div class="zh-write-ctrl">
          <button class="pbtn primary" data-hzw="anim">▶ Xem thứ tự nét</button>
          <button class="pbtn" data-hzw="quiz">✎ Luyện viết</button>
          <button class="pbtn" data-hzw="reset">↺ Làm lại</button>
          <button class="pbtn" data-zh-speak="${esc(cur)}">🔊 Nghe</button>
        </div>
      </div>
    </div>
    <div class="zh-write-pick">
      <div class="zh-write-pick-head">
        <div class="eyebrow">Chọn chữ để luyện · ${chars.length} chữ</div>
        <div class="level-strip compact">
          ${_ZC.levels.filter(v => v.status === 'active').map(v => `<button class="level-chip" data-zh-wlevel="${v.id}"${wl === v.id ? ' aria-pressed="true"' : ''}>${esc(v.zh)}</button>`).join('')}
        </div>
      </div>
      <div class="hz-chips">${chars.map(c => `<button class="hz-chip ko${c === cur ? ' on' : ''}" data-zh-write="${esc(c)}">${esc(c)}</button>`).join('')}</div>
    </div>
  </div>`;
};

function zhDictResults(q){
  const norm = s => (s || '').toLowerCase();
  const strip = s => norm(s).normalize('NFD').replace(/[̀-ͯ]/g, '');
  q = (q || '').trim();
  let items = Object.values(ZH_LOOKUP);
  if (q){
    const ql = norm(q), qs = strip(q);
    items = items.filter(w => w.zh.indexOf(q) >= 0 || strip(w.pinyin).indexOf(qs) >= 0 || norm(w.vi).indexOf(ql) >= 0 || norm(w.hv).indexOf(ql) >= 0);
  }
  const total = items.length;
  items = items.slice(0, 80);
  if (!items.length) return `<p class="zh-empty">Không thấy từ nào khớp. Thử gõ chữ Hán hoặc pinyin không dấu.</p>` + crossDictHint(q, 'zh');
  const head = `<div class="zh-res-count">${total} từ${total > 80 ? ' · hiện 80 đầu, gõ thêm để thu hẹp' : ''}</div>` + crossDictHint(q, 'zh');
  return head + items.map(w => `
    <div class="zh-res">
      <div class="zh-res-hz ko" data-zh-write="${esc(w.zh[0])}">${esc(w.zh)}</div>
      <div class="zh-res-mid">
        <div><span class="py">${esc(w.pinyin)}</span> · <b>${esc(w.hv)}</b></div>
        <div class="zh-res-vi">${esc(w.vi)}</div>
        <div class="zh-res-meta">${esc(w.pos)} · ${w.refs.map(r => `<button class="zh-ref" data-zh-open="${r.lv}:${r.no}" title="Mở bài học">${esc(zhLevelName(r.lv))} bài ${r.no}</button>`).join(' ')}</div>
      </div>
      <div class="zh-res-act">
        <button class="icon-btn" data-zh-speak="${esc(w.zh)}" title="Nghe">🔊</button>
        <a class="icon-btn" href="https://hvdic.thivien.net/whv/${encodeURIComponent(w.zh)}" target="_blank" rel="noopener noreferrer" title="Tra Hán–Việt">↗</a>
      </div>
    </div>`).join('');
}
VIEWS.zh_dict = function(){
  const q = state.zh.dictQ || '';
  return `
  <div class="page-head">
    <span class="eyebrow">Tiếng Trung</span>
    <h1>Từ điển</h1>
    <p>Gõ chữ Hán, pinyin hoặc nghĩa tiếng Việt để tra trong ${Object.keys(ZH_LOOKUP).length} từ của khoá HSK 1–${_ZC.levels.filter(v => v.status === 'active').length}. Bấm chữ trong bài học cũng mở tra ở đây; bấm nhãn bài để nhảy tới bài học.</p>
  </div>
  <div class="zh-dict-search">
    <svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg>
    <input id="zhq" type="search" value="${esc(q)}" placeholder="你好 / nǐ hǎo / xin chào…" autocomplete="off">
  </div>
  <div id="zhResults" class="zh-results">${zhDictResults(q)}</div>`;
};

VIEWS.zh_srs = function(){
  const lv = zhPracLevel(), deck = zhPool(lv);
  if (!state.zh.srs || state.zh.srs.n !== deck.length || state.zh.srs.lv !== lv) state.zh.srs = { i:0, show:false, n:deck.length, lv };
  const s = state.zh.srs;
  const w = deck[s.i % deck.length] || deck[0] || { zh:'你', pinyin:'nǐ', vi:'bạn', hv:'nễ', pos:'' };
  return `
  <div class="page-head">
    <span class="eyebrow">Tiếng Trung</span>
    <h1>Ôn tập từ vựng</h1>
    <p>Thẻ ghi nhớ ${deck.length} từ ${lv === 'all' ? 'mọi cấp' : esc(zhLevelName(lv))}. Nhìn chữ, đoán nghĩa rồi lật thẻ.</p>
  </div>
  ${zhLevelChips('data-zh-prac', lv, true)}
  <div class="zh-srs">
    <div class="zh-card ${s.show ? 'open' : ''}" id="zhCard">
      <div class="zh-card-front ko">${esc(w.zh)}</div>
      <div class="zh-card-back"><div class="py">${esc(w.pinyin)}</div><div class="zh-card-vi">${esc(w.vi)}</div><div class="zh-card-hv">${esc(w.hv)} · ${esc(w.pos)}</div></div>
    </div>
    <div class="zh-srs-ctrl">
      <button class="pbtn" data-zh-speak="${esc(w.zh)}">🔊 Nghe</button>
      <button class="pbtn primary" id="zhFlip">${s.show ? 'Ẩn đáp án' : 'Lật thẻ'}</button>
      <button class="pbtn" data-zh-srs="next">Thẻ sau →</button>
    </div>
    <div class="zh-srs-count">${(s.i % deck.length) + 1} / ${deck.length}</div>
  </div>`;
};

/* ---------------- Bài tập & Thi thử (ZH) ---------------- */
function zhPick(a){ return a[Math.floor(Math.random() * a.length)]; }
function zhShuffle(a){ a = a.slice(); for (let i = a.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); const t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
function zhDistract(pool, key, val, n){
  const seen = {}; seen[val] = 1; const out = [];
  for (const x of zhShuffle(pool)){ const v = x[key]; if (!seen[v]){ seen[v] = 1; out.push(v); if (out.length >= n) break; } }
  return out;
}
function zhMakeQuestions(n){
  const pool = zhPool(zhPracLevel());
  const qs = [], used = {}; let guard = 0;
  while (qs.length < n && guard++ < n * 40){
    const w = zhPick(pool), type = zhPick(['mean','char','pinyin']);
    const key = w.zh + '|' + type; if (used[key]) continue; used[key] = 1;
    let q;
    if (type === 'mean')
      q = { prompt:'Từ này nghĩa là gì?', main:`<span class="ko qz-hz">${esc(w.zh)}</span> <span class="py">${esc(w.pinyin)}</span>`,
            opts: zhShuffle([w.vi].concat(zhDistract(pool,'vi',w.vi,3))), answer:w.vi, oc:'' };
    else if (type === 'char')
      q = { prompt:'Chọn chữ đúng với nghĩa:', main:`<b>${esc(w.vi)}</b> <span class="py">(${esc(w.pinyin)})</span>`,
            opts: zhShuffle([w.zh].concat(zhDistract(pool,'zh',w.zh,3))), answer:w.zh, oc:'ko' };
    else
      q = { prompt:'Chọn pinyin đúng:', main:`<span class="ko qz-hz">${esc(w.zh)}</span>`,
            opts: zhShuffle([w.pinyin].concat(zhDistract(pool,'pinyin',w.pinyin,3))), answer:w.pinyin, oc:'py' };
    q.explain = `${w.zh} · ${w.pinyin} · ${w.hv} — ${w.vi}`;
    qs.push(q);
  }
  return qs;
}
function zhFmtTime(s){ s = Math.max(0, s); const m = Math.floor(s / 60), ss = s % 60; return m + ':' + (ss < 10 ? '0' : '') + ss; }

VIEWS.zh_quiz = function(){
  const Q = state.zh.quiz;
  if (!Q || !Q.qs){
    return `
    <div class="page-head"><span class="eyebrow">Tiếng Trung · Bài tập</span><h1>Bài tập trắc nghiệm</h1>
      <p>10 câu ngẫu nhiên từ vốn từ ${zhPracLevel() === 'all' ? 'mọi cấp' : esc(zhLevelName(zhPracLevel()))} (${zhPool(zhPracLevel()).length} từ): đoán nghĩa, chọn chữ, chọn pinyin — có chấm điểm và giải thích.</p></div>
    ${zhLevelChips('data-zh-prac', zhPracLevel(), true)}
    <div class="stage-ctrl"><button class="pbtn primary" data-zh-qz-start="1">▶ Bắt đầu 10 câu</button></div>`;
  }
  if (Q.i >= Q.qs.length){
    const score = Q.picked.filter((p, i) => p === Q.qs[i].answer).length, pct = Math.round(score / Q.qs.length * 100);
    return `
    <div class="page-head"><span class="eyebrow">Tiếng Trung · Bài tập</span><h1>Kết quả: ${score}/${Q.qs.length}</h1>
      <p>Đúng ${pct}%. ${pct >= 80 ? 'Giỏi lắm!' : pct >= 50 ? 'Khá rồi, ôn thêm chút nhé.' : 'Cần luyện thêm nhé.'}</p></div>
    <div class="qz-review">${Q.qs.map((q, i) => `<div class="qz-rev ${Q.picked[i] === q.answer ? 'ok' : 'no'}"><span>${Q.picked[i] === q.answer ? '✓' : '✗'}</span> ${esc(q.explain)}</div>`).join('')}</div>
    <div class="stage-ctrl"><button class="pbtn primary" data-zh-qz-start="1">↻ Làm lại</button></div>`;
  }
  const q = Q.qs[Q.i], picked = Q.picked[Q.i];
  return `
  <div class="page-head"><span class="eyebrow">Tiếng Trung · Bài tập</span><h1>Bài tập <span class="qz-count">${Q.i + 1}/${Q.qs.length}</span> <button class="mini" data-zh-qz-start="1" title="Bỏ đề này, sinh đề mới">↻ Đề khác</button></h1><p>${esc(q.prompt)}</p></div>
  <div class="qz-main">${q.main}</div>
  <div class="qz-opts">${q.opts.map(o => {
    let cls = 'qz-opt' + (q.oc ? ' ' + q.oc : '');
    if (picked != null){ if (o === q.answer) cls += ' correct'; else if (o === picked) cls += ' wrong'; }
    return `<button class="${cls}" data-zh-qz="${esc(o)}"${picked != null ? ' disabled' : ''}>${esc(o)}</button>`;
  }).join('')}</div>
  ${picked != null ? `<div class="qz-explain ${picked === q.answer ? 'ok' : 'no'}">${picked === q.answer ? '✓ Đúng! ' : '✗ Chưa đúng. '}${esc(q.explain)}</div>
    <div class="stage-ctrl"><button class="pbtn primary" data-zh-qz-next="1">${Q.i + 1 < Q.qs.length ? 'Câu sau →' : 'Xem kết quả'}</button></div>` : ''}`;
};

/* ============================================================
   TIẾNG NGA (русский язык) — bảng chữ cái · phát âm · tập viết · khoá A1–C2 · luyện nói · ТРКИ
   ============================================================ */
const _RC = (typeof COURSE_RU   !== 'undefined') ? COURSE_RU   : { levels:[], lessons:[] };
const _RA = (typeof ALPHABET_RU !== 'undefined') ? ALPHABET_RU : [];
const _RP = (typeof PHON_RU     !== 'undefined') ? PHON_RU     : [];
const _RS = (typeof SPEAKING_RU !== 'undefined') ? SPEAKING_RU : [];

/* Bỏ dấu trọng âm (U+0301) — dùng khi đọc máy, tìm kiếm, so sánh */
function ruPlain(s){ return String(s || '').replace(/́/g, ''); }
function ruKey(s){ return ruPlain(s).toLowerCase().replace(/ё/g, 'е'); }

const RU_LOOKUP = (function(){
  const m = {};
  _RC.lessons.forEach(l => l.vocab.forEach(w => {
    const lv = l.level || 'a1', k = ruPlain(w.ru);
    if (!m[k]) m[k] = Object.assign({ key:k, refs:[], levels:[] }, w);
    const e = m[k];
    if (!e.refs.some(r => r.lv === lv && r.no === l.no)) e.refs.push({ lv, no:l.no });
    if (e.levels.indexOf(lv) < 0) e.levels.push(lv);
  }));
  /* gộp kho nghĩa soạn tay (js/dict-ru.js): thêm mục từ lõi chưa có trong bài, gắn nghĩa mở rộng cho mục đã có */
  const D = (typeof RU_DICT !== 'undefined') ? RU_DICT : {};
  const byKey = {}; Object.keys(m).forEach(k => { byKey[ruKey(k)] = k; });
  Object.keys(D).forEach(dk => {
    const d = D[dk], k = byKey[ruKey(dk)];
    if (k) m[k].dict = d;
    else m[dk] = { key:dk, ru:d.ru || dk, vi:d.vi || (d.senses && d.senses[0] ? d.senses[0].vi : ''), pos:d.pos || '', note:'', refs:[], levels:[], dict:d };
  });
  return m;
})();
const _RM = (typeof RuMorph !== 'undefined') ? RuMorph : null;
/* Chỉ mục dạng biến đổi → từ gốc (để bấm «зову́т» ra «звать»); dựng lười lần đầu */
let _ruFormIdx = null;
function ruFormIndex(){
  if (_ruFormIdx) return _ruFormIdx;
  const idx = {};
  const add = (form, key) => { const f = ruKey(form); if (!f) return; (idx[f] = idx[f] || []); if (idx[f].indexOf(key) < 0) idx[f].push(key); };
  Object.values(RU_LOOKUP).forEach(w => {
    const parts = String(w.ru).split(/\s*\/\s*/);
    parts.forEach(part => {
      const plain = ruPlain(part).trim();
      if (!plain) return;
      if (/\s/.test(plain)){ add(plain, w.key); plain.split(/\s+/).forEach(t => { if (t.length > 3) add(t.replace(/[^А-Яа-яЁё-]/g, ''), w.key); }); return; }
      add(plain, w.key);
      if (_RM){ try { _RM.allForms(part.trim(), w.pos, w.vi).forEach(f => add(f, w.key)); } catch(e){} }
    });
  });
  _ruFormIdx = idx; return idx;
}
/* Tìm mục từ cho một từ bấm trong câu: đúng từ gốc → dạng biến đổi → cụm có chứa */
function ruLemmatize(tok){
  const k = ruKey(String(tok).replace(/[^А-Яа-яЁё́-]/g, ''));
  if (!k) return [];
  const exact = Object.values(RU_LOOKUP).filter(w => ruKey(w.ru) === k || String(w.ru).split(/\s*\/\s*/).some(p => ruKey(p) === k));
  if (exact.length) return exact.map(w => w.key);
  const hit = ruFormIndex()[k];
  if (hit && hit.length) return hit.filter(key => !/\s/.test(ruPlain(key))).concat(hit.filter(key => /\s/.test(ruPlain(key))));
  return [];
}
try { window.__ruDict = { lemmatize: ruLemmatize, lookup: RU_LOOKUP, forms: ruFormIndex }; } catch(e){}
/* Bấm một từ trong câu: mở mục từ nếu tìm được từ gốc, không thì tìm gần đúng */
function ruOpenWord(tok){
  const keys = ruLemmatize(tok);
  state.ru.dictQ = ruPlain(tok);
  state.ru.entry = keys.length ? keys[0] : null;
  if (state.view !== 'ru_dict') go('ru_dict'); else render();
  try { window.scrollTo({ top:0 }); } catch(e){}
}

/* ---- Phát âm tiếng Anh (dùng giọng en-GB nếu có, không thì en-US) ---- */
function enSpeak(text, variant){
  try {
    const synth = window.speechSynthesis; if (!synth){ toast('Trình duyệt chưa hỗ trợ phát âm'); return; }
    const plain = String(text || '').replace(/[\u2018\u2019]/g, "'").replace(/[\u201C\u201D]/g, '"').trim();
    if (!plain) return;
    const want = variant || store.get('enVoice', 'uk');
    let done = false;
    const speak = () => {
      if (done) return; done = true;
      synth.cancel();
      const u = new SpeechSynthesisUtterance(plain);
      u.lang = want === 'us' ? 'en-US' : 'en-GB'; u.rate = 0.9;
      const vs = synth.getVoices() || [];
      const pref = want === 'us' ? /en[-_]us|american/i : /en[-_]gb|british|united kingdom/i;
      const v = vs.find(x => pref.test((x.lang || '') + ' ' + (x.name || ''))) || vs.find(x => /^en\b|en[-_]/i.test(x.lang || ''));
      if (v) u.voice = v;
      else if (!enSpeak._warned){ enSpeak._warned = true; toast('Máy chưa có giọng đọc tiếng Anh — cài gói giọng en-GB hoặc en-US trong hệ điều hành.'); }
      synth.speak(u);
    };
    const vs = synth.getVoices() || [];
    if (vs.length) speak();
    else { try { synth.addEventListener('voiceschanged', speak, { once:true }); } catch(e){} setTimeout(speak, 300); }
  } catch(e){}
}
function enSpeakBtn(text, cls){ return `<button class="${cls || 'icon-btn'}" data-en-speak="${esc(text)}" title="Nghe">\ud83d\udd0a</button>`; }
function ruSpeak(text){
  try {
    const synth = window.speechSynthesis; if (!synth){ toast('Trình duyệt chưa hỗ trợ phát âm'); return; }
    const plain = ruPlain(text);
    let done = false;
    const speak = () => {
      if (done) return; done = true;
      synth.cancel();
      const u = new SpeechSynthesisUtterance(plain);
      u.lang = 'ru-RU'; u.rate = 0.85;
      const vs = synth.getVoices() || [];
      const ru = vs.find(v => /^ru\b|ru[-_]|russian|русск/i.test((v.lang || '') + ' ' + (v.name || '')));
      if (ru) u.voice = ru;
      else if (!ruSpeak._warned && !vs.some(v => /^ru/i.test(v.lang || ''))){ ruSpeak._warned = true; toast('Máy chưa có giọng đọc tiếng Nga — cài gói giọng ru-RU (Русский) trong hệ điều hành.'); }
      synth.speak(u);
    };
    const vs = synth.getVoices() || [];
    if (vs.length) speak();
    else { try { synth.addEventListener('voiceschanged', speak, { once:true }); } catch(e){} setTimeout(speak, 300); }
  } catch(e){}
}
/* Lời đọc bài nghe ТРКИ: bỏ nhãn người nói, gạch đầu dòng */
function ruSpeech(a){ return ruPlain(String(a || '')).replace(/(^|\s)[—–-]\s*/g, '$1').replace(/(Он|Она|Диктор|Мужчина|Женщина|Вопрос|Журналист|Гид|Продавец|Покупатель|Врач|Пациент|Студент|Преподаватель|[А-ЯЁ][а-яё]+)\s*:\s*/g, ''); }

function ruLevel(){ return _RC.levels.find(x => x.id === state.ru.level) || _RC.levels[0] || { vi:'A1', ru:'A1' }; }
function ruLevelName(id){ const v = _RC.levels.find(x => x.id === id); return v ? v.ru.split(' ')[0] : (id || '').toUpperCase(); }
function ruLessonList(){ return _RC.lessons.filter(l => l.level === state.ru.level); }
function ruCurLesson(){ return _RC.lessons.find(l => l.no === state.ru.lesson && l.level === state.ru.level); }
function ruPracLevel(){
  const ids = _RC.levels.filter(v => v.status === 'active').map(v => v.id);
  const cur = state.ru.pracLevel || state.ru.level;
  return cur === 'all' ? 'all' : (ids.indexOf(cur) >= 0 ? cur : (ids[0] || 'a1'));
}
function ruPool(level){
  const all = Object.values(RU_LOOKUP);
  if (!level || level === 'all') return all;
  const p = all.filter(w => w.levels.indexOf(level) >= 0);
  return p.length >= 12 ? p : all;
}
function ruLevelChips(attr, cur, withAll){
  const act = _RC.levels.filter(v => v.status === 'active');
  return `<div class="level-strip compact">${act.map(v => `<button class="level-chip" ${attr}="${v.id}"${cur === v.id ? ' aria-pressed="true"' : ''}>${esc(ruLevelName(v.id))}</button>`).join('')}${withAll ? `<button class="level-chip" ${attr}="all"${cur === 'all' ? ' aria-pressed="true"' : ''}>Tất cả</button>` : ''}</div>`;
}
function ruCrumb(){
  const map = { ru_home:'Khoá học', ru_alphabet:'Bảng chữ cái', ru_phonetics:'Phát âm', ru_write:'Tập viết', ru_dict:'Từ điển',
    ru_srs:'Ôn tập', ru_quiz:'Bài tập', ru_speak:'Luyện nói', ru_exam:'Thi thử ТРКИ' };
  const L = ruCurLesson();
  if (state.view === 'ru_lesson' && L)
    return `<button class="crumb-link" data-go="ru_home">Tiếng Nga</button> <span>›</span> <button class="crumb-link" data-go="ru_home">${esc(ruLevelName(state.ru.level))}</button> <span>›</span> <b>Bài ${String(L.no).padStart(2,'0')} · ${esc(L.vi)}</b>`;
  return `<button class="crumb-link" data-go="ru_home">Tiếng Nga</button> <span>›</span> <b>${esc(map[state.view] || '')}</b>`;
}
/* Từ trong câu bấm được → tra từ điển (bỏ dấu câu, giữ dấu trọng âm để hiển thị) */
function ruTokens(str){
  return String(str || '').split(/(\s+)/).map(tok => {
    if (!tok.trim()) return esc(tok);
    const m = tok.match(/^([^А-Яа-яЁё]*)([А-Яа-яЁё́-]+)([^А-Яа-яЁё]*)$/u);
    if (!m) return esc(tok);
    return esc(m[1]) + `<span class="zc ru-tok" data-ruw="${esc(ruPlain(m[2]))}" title="Tra từ này">${esc(m[2])}</span>` + esc(m[3]);
  }).join('');
}
function ruSpeakBtn(text, cls){ return `<button class="${cls || 'icon-btn'}" data-ru-speak="${esc(ruPlain(text))}" title="Nghe">🔊</button>`; }

/* ---------------- Views tiếng Nga ---------------- */
